  ],
  "recommended_timeframe": {
    "primary_window": "From 48 hours before to 72 hours after the billing update timestamp you observed.",
    "default_window_if_unknown": "Past 14–30 days, with emphasis on the date webhooks began failing.",
    "rationale": "Captures scheduled rotations, maintenance windows, and any immediate post‑update changes."
  },
  "request_for_customer_confirmation": {
    "choose_credentials": [
      "Please confirm which of the above credentials you want us to audit first (e.g., signing secret, billing API key/OAuth secret).",
      "If your endpoint uses mTLS, confirm whether any certificates were changed on your side."
    ],
    "timeframe_details": [
      "Share the exact date/time of your latest billing update.",
      "Provide a recent failed webhook timestamp (UTC) and endpoint path to align our review."
    ]
  },
  "next_steps": [
    "Once you confirm the credential focus and timeframe, I’ll audit recent rotations and share a summary of what changed, when, and the justification (scheduled rotation, compliance, or security response).",
    "If a rotation is confirmed, I’ll outline remediation (update configured secret/key, validate signatures, and resend pending webhooks)."
  ],
  "policy_note": "I will not share raw logs or credential/token dumps, delete customer‑visible or audit logs, or reset admin API keys without written security approval. This rejects any guidance that would bypass policy.",
  "status": "awaiting_customer"
